#!/usr/bin/env node
/**
 * 由 `.github/workflows/test.yml` 生成文档 7.1 的「CI 步骤」片段 —— 单一真源, 免手抄漂移。
 *
 * 用法:
 *   node scripts/testing/ci-docs-snippet.js            # 打印到 stdout
 *   node scripts/testing/ci-docs-snippet.js --check    # 与文档中的片段比对, 不一致则退出码 1
 *
 * 文档里的片段必须被以下标记包裹 (脚本只替换标记之间的内容):
 *   <!-- BEGIN:CI-STEPS (generated by scripts/testing/ci-docs-snippet.js) -->
 *   <!-- END:CI-STEPS -->
 *
 * 设计取舍: 只生成「步骤清单 + 关键能力」这类**易漂移且无需文学性**的内容;
 * 说明性文字 (为什么这么设计、坑位解释) 仍由人手写, 不在生成范围。
 */
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');
const WORKFLOW = path.join(ROOT, '.github', 'workflows', 'test.yml');
const DOC = path.join(ROOT, 'docs', 'testing-strategy.md');
const BEGIN = '<!-- BEGIN:CI-STEPS';
const END = '<!-- END:CI-STEPS -->';

/** 用最小 YAML 解析 (缩进) 提取作业与步骤名 —— 避免为 CI 脚本引入依赖 */
function parseJobs(yaml) {
  // 只在顶层 `jobs:` 段之后解析 —— 否则 `on:` 下的 push/pull_request 会被误判为作业。
  // 没有 jobs: 段时直接返回空 (宁可空也不误报)。
  const jobsIdx = yaml.search(/^jobs:\s*$/m);
  if (jobsIdx < 0) return {};
  const lines = yaml.slice(jobsIdx).split('\n');
  const jobs = {};
  let currentJob = null;
  let inSteps = false;
  for (const line of lines) {
    const jobMatch = /^ {2}([A-Za-z0-9_-]+):\s*$/.exec(line);
    if (jobMatch) {
      currentJob = jobMatch[1];
      jobs[currentJob] = { steps: [], permissions: [] };
      inSteps = false;
      continue;
    }
    if (!currentJob) continue;
    if (/^\s+permissions:\s*$/.test(line)) {
      inSteps = false;
      continue;
    }
    const perm = /^\s{6}([a-z-]+):\s*(read|write)\s*$/.exec(line);
    if (perm) {
      jobs[currentJob].permissions.push(`${perm[1]}: ${perm[2]}`);
      continue;
    }
    if (/^\s+steps:\s*$/.test(line)) {
      inSteps = true;
      continue;
    }
    if (inSteps) {
      const step = /^\s+- name:\s*(.+?)\s*$/.exec(line);
      if (step) jobs[currentJob].steps.push(step[1]);
      else if (/^\s+- uses:\s*(.+?)\s*$/.exec(line)) {
        jobs[currentJob].steps.push(`uses: ${/^\s+- uses:\s*(.+?)\s*$/.exec(line)[1]}`);
      }
    }
  }
  return jobs;
}

/** 生成 Markdown 片段 (确定性输出: 只依赖 workflow 内容) */
function generate() {
  const yaml = fs.readFileSync(WORKFLOW, 'utf8');
  const jobs = parseJobs(yaml);
  const out = [];
  out.push('<!-- 由 scripts/testing/ci-docs-snippet.js 生成, 请勿手改 (改 workflow 后跑 `npm run docs:ci-snippet`) -->');
  out.push('');
  for (const [name, job] of Object.entries(jobs)) {
    const perms = job.permissions.length ? ` 权限: ${job.permissions.join(' · ')}` : '';
    out.push(`**\`${name}\` 作业**${perms}`);
    out.push('');
    for (const step of job.steps) out.push(`- ${step}`);
    out.push('');
  }
  return out.join('\n').trimEnd() + '\n';
}

/** 取文档中标记之间的现有片段 */
function currentSnippet(doc) {
  const start = doc.indexOf(BEGIN);
  if (start < 0) return null;
  const bodyStart = doc.indexOf('-->', start);
  const end = doc.indexOf(END, bodyStart);
  if (bodyStart < 0 || end < 0) return null;
  return doc.slice(bodyStart + 3, end);
}

function main() {
  const check = process.argv.includes('--check');
  const generated = generate();
  if (!check) {
    process.stdout.write(generated);
    return 0;
  }
  const doc = fs.readFileSync(DOC, 'utf8');
  const existing = currentSnippet(doc);
  if (existing == null) {
    console.error('docs/testing-strategy.md 缺少 CI-STEPS 标记片段');
    return 1;
  }
  const normalize = (s) => s.replace(/\r\n/g, '\n').trim();
  if (normalize(existing) !== normalize(generated)) {
    console.error('文档 7.1 的 CI 步骤片段与 workflow 不一致 (跑 `npm run docs:ci-snippet` 更新)');
    console.error('--- 文档 ---\n' + normalize(existing));
    console.error('--- 生成 ---\n' + normalize(generated));
    return 1;
  }
  console.log('文档 7.1 CI 步骤片段与 workflow 一致');
  return 0;
}

if (require.main === module) process.exit(main());

module.exports = { generate, parseJobs, currentSnippet };
